const input = $json;
return [{
  json: {
    study_id: input.study_id,
    building_id: input.building_id ?? null,
    zone_ids: input.zone_ids ?? [],
    behavior_targets: input.behavior_targets ?? [],
    date_range: input.date_range ?? null,
    snapshot_folder_url: $env.HA_SNAPSHOT_FOLDER_URL || 'http://<YOUR_HA_URL>:8123/local/snapshots/',
    image_selection_rules: {
      max_images_per_run: input.image_selection_rules?.max_images_per_run ?? 25,
      filename_match: input.image_selection_rules?.filename_match ?? null,
    },
    setup_instructions: input.setup_instructions ?? '',
    debug_mode: input.debug_mode ?? false,
  }
}];

const monitor = $('Prepare Monitoring Request').item.json;
const raw = typeof $json === 'string'
  ? $json
  : ($json.body ?? $json.data ?? $json.response ?? $json);

let html = '';
if (typeof raw === 'string') {
  html = raw;
} else if (Array.isArray(raw)) {
  html = raw.join('\n');
} else if (raw && typeof raw === 'object') {
  html = JSON.stringify(raw);
}

let files = [];
try {
  const maybeJson = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (Array.isArray(maybeJson)) files = maybeJson;
} catch {}

const hrefMatches = [...html.matchAll(/(?:href|src)=["']([^"'?#]+\.(?:jpg|jpeg|png|webp))["']/gi)].map((m) => m[1]);
files = files.length ? files : hrefMatches;

const unique = [...new Set(files)]
  .map((entry) => {
    const url = typeof entry === 'string'
      ? entry
      : (entry.url ?? entry.href ?? entry.path ?? null);
    return url;
  })
  .filter(Boolean)
  .map((entry) => {
    try {
      return new URL(entry, monitor.snapshot_folder_url).toString();
    } catch {
      return null;
    }
  })
  .filter(Boolean)
  .filter((entry) => /\.(jpg|jpeg|png|webp)$/i.test(entry));

const filtered = unique
  .filter((entry) => {
    const pattern = monitor.image_selection_rules.filename_match;
    if (!pattern) return true;
    return entry.includes(pattern);
  })
  .sort((a, b) => b.localeCompare(a))
  .slice(0, monitor.image_selection_rules.max_images_per_run ?? 25);

return filtered.map((imageUrl) => ({
  json: {
    study_id: monitor.study_id,
    building_id: monitor.building_id,
    zone_ids: monitor.zone_ids,
    behavior_targets: monitor.behavior_targets,
    image_id: imageUrl.split('/').pop(),
    timestamp: new Date().toISOString(),
    zone_id: monitor.zone_ids[0] ?? null,
    image_url: imageUrl,
    setup_instructions: monitor.setup_instructions,
  }
}));

