const response = $json.output?.[0]?.content?.[0]?.text ?? $json.output_text ?? $json.output ?? $json;
let parsed = response;
const studyInput = $items('Extract Latest Snapshot Links', 0, $itemIndex)[0].json;
let error = null;
try {
  if (typeof parsed === 'string') parsed = JSON.parse(parsed);
} catch (e) {
  error = 'vision_json_parse_failed';
  parsed = {};
}
return [{
  json: {
    study_id: studyInput.study_id,
    image_id: studyInput.image_id,
    timestamp: studyInput.timestamp,
    zone_id: studyInput.zone_id,
    detected_behaviors: parsed.detected_behaviors ?? [],
    confidence_scores: parsed.confidence_scores ?? {},
    notes: parsed.notes ?? (error ? 'Skipped due to parse failure' : ''),
    model_version: parsed.model_version ?? ($env.VISION_MODEL || 'gpt-4.1-mini'),
    parse_error: error,
  }
}];

const items = $input.all().map(i => i.json);
return [{
  json: {
    detection_log: items,
    behavior_summary: {
      images_processed: items.length,
      behaviors_detected: Array.from(new Set(items.flatMap(i => i.detected_behaviors.map(b => b.name ?? b))))
    },
    monitoring_status: {
      status: 'batch_complete',
      skipped_images: items.filter(i => i.parse_error).length
    },
    study_dataset_reference: {
      table: 'behavior_detections',
      study_id: items[0]?.study_id ?? $('Prepare Monitoring Request').item.json.study_id
    }
  }
}];
